import os
import glob
from collections import Counter

def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"The specified directory does not exist: {directory}")

    counts = Counter({ext: 0 for ext in extensions})

    for ext in extensions:
        pattern = os.path.join(directory, '**', f'*{ext}')
        files = glob.glob(pattern, recursive=True)
        counts[ext] = len(files)

    if keep_zero and counts[extensions[-1]] == 0 and counts[extensions[0]] == 0:
        counts[extensions[-1]] = 1

    if not keep_zero:
        counts = Counter({ext: cnt for ext, cnt in counts.items() if cnt > 0})

    return counts

