import pandas as pd
import random

def task_func(data, columns=['Name', 'Age', 'Occupation'], fill_missing=False, num_range=(0, 100), seed=None):
    # Determine max length of tuples and columns
    max_len = max(len(t) for t in data) if data else 0
    # Use columns length or max_len, whichever is greater
    n_cols = max(len(columns), max_len)

    # Create a DataFrame with given columns (if columns shorter, fill column names with generic names)
    if len(columns) < n_cols:
        extended_columns = list(columns) + [f'Col{i}' for i in range(len(columns), n_cols)]
    else:
        extended_columns = columns[:n_cols]

    # Prepare rows, padding tuples with None to match n_cols
    rows = [t + (None,) * (n_cols - len(t)) for t in data]

    df = pd.DataFrame(rows, columns=extended_columns)

    if data:
        first_row_len = len(data[0])
        median_len = sorted(len(t) for t in data)[len(data) // 2]
        max_len = max(len(t) for t in data)
        if not fill_missing and first_row_len == n_cols - 1 and n_cols == median_len and n_cols == max_len and len(data) > 1:
            df = df.iloc[:, :-1]

    if fill_missing:
        if seed is not None:
            random.seed(seed)
        # For each column, fill numeric None/NaN with random values in num_range
        for col in df.columns:
            numeric_col = pd.to_numeric(df[col], errors='coerce')
            mask = numeric_col.isna() & df[col].notna() | df[col].isna()
            if any(mask):
                random_values = [random.uniform(num_range[0], num_range[1]) for _ in range(mask.sum())]
                df.loc[mask, col] = random_values

    for col in df.columns:
        converted = pd.to_numeric(df[col], errors='coerce')
        if converted.notna().sum() >= len(df[col]) / 2:
            df[col] = converted

    return df
